uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// Parameter mappings
uniform float u_speed;
uniform float u_scale;
uniform float u_intensity;
uniform float u_color_cycle;
uniform float u_layers;
uniform float u_density;
uniform float u_connection_radius;
uniform float u_pulse_intensity;
uniform float u_color_base;
uniform float u_color_pulse;
uniform float u_neon_glow;
uniform float u_bloom;

out vec4 fragColor;

// --- Helper Functions ---

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

vec2 hash22(vec2 p) {
    float n = hash21(p);
    return vec2(n, hash21(p + n));
}

float vnoise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float getLife(vec2 cellId, float t) {
    float r = length(cellId);
    vec2 dir = (r > 0.001) ? (cellId / r) : vec2(0.0);
    float n = vnoise(cellId * 0.2 - dir * t * 0.5 + vec2(t * 0.1));
    float coreBias = exp(-r * 0.08);
    return smoothstep(0.3, 0.6, n * coreBias);
}

float distLine(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}

vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

// Evaluates Connections with neon logic
void evalConnection(vec2 f, vec2 p1, float life1, vec2 offs, vec2 dir, vec2 id, float t, float connRadius, inout vec4 lineData, inout float glow) {
    vec2 cellId = id + offs;
    vec2 neighborId = cellId + dir;

    float life2 = getLife(neighborId, t);

    if (life2 > 0.0) {
        vec2 p2 = offs + dir + 0.5 + 0.3 * sin(t * 1.5 + hash22(neighborId) * 6.28);
        float dConn = distance(p1, p2);

        if (dConn < connRadius) {
            float dLine = distLine(f, p1, p2);
            float lineAlpha = min(life1, life2); 

            float px = 0.015;
            float thickness = 0.012 * lineAlpha;
            float shape = smoothstep(thickness + px, thickness, dLine);

            // Neon Glow calculation: softer distance falloff for light leakage
            float neon = exp(-dLine * 45.0) * u_neon_glow;
            glow += neon * lineAlpha * smoothstep(connRadius, connRadius * 0.5, dConn);

            if (shape > 0.0 || neon > 0.01) {
                float r = length(cellId);
                float pulse = smoothstep(0.7, 1.0, sin(r * 0.8 - t * 6.0));
                pulse *= smoothstep(connRadius, connRadius * 0.7, dConn);

                lineData.a = max(lineData.a, shape * lineAlpha);
                lineData.r = max(lineData.r, pulse * lineAlpha);
            }
        }
    }
}

void main() {
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;

    vec2 mouseOffset = (iMouse.z > 0.0) ? (iMouse.xy / iResolution.xy - 0.5) : vec2(0.0);

    float spd = (u_speed <= 0.0) ? 0.3 : u_speed;
    float t = iTime * spd;

    float breathe = 1.0 + 0.08 * sin(t * 1.2); 

    float scaleBase = (u_scale <= 0.0) ? 1.0 : u_scale;
    float layerCount = clamp(u_layers, 1.0, 8.0);
    float density = (u_density <= 0.0) ? 1.0 : u_density * 2.0; 
    float connRadius = ((u_connection_radius <= 0.0) ? 1.5 : u_connection_radius * 2.5) * breathe;
    float pulseInt = u_pulse_intensity * 2.0;

    // Neon Hue Shifts
    float hueBase = fract(u_color_base + (t * u_color_cycle * 0.05));
    float huePulse = fract(u_color_pulse + (t * u_color_cycle * 0.05));

    // High Saturation for Neon look
    vec3 baseCol = hsv2rgb(vec3(hueBase, 0.9, 1.0));
    vec3 pulseCol = hsv2rgb(vec3(huePulse, 0.85, 1.0));

    // Lush Dark Background with a hint of color
    vec3 bgCenter = baseCol * 0.08; 
    vec3 bgEdge = vec3(0.005, 0.008, 0.012);
    vec3 finalColor = mix(bgCenter, bgEdge, length(uv0) * 1.5);

    for(int i = 0; i < 8; i++) {
        float fi = float(i);
        if(fi >= layerCount) break;

        float z = fract(fi * 0.15 + t * 0.04); 
        float fade = smoothstep(0.0, 0.3, z) * smoothstep(1.0, 0.8, z);

        float size = mix(15.0, 2.0, z) * scaleBase * density;

        vec2 layerUV = (uv + mouseOffset * (1.0 - z) * 0.8) * size;
        layerUV *= rot(z * 0.5 + fi * 1.5);

        vec2 id = floor(layerUV);
        vec2 f = fract(layerUV);

        float nodeMask = 0.0;
        float nodeGlow = 0.0;
        vec4 lineData = vec4(0.0); 
        float lineGlow = 0.0;

        for(int y = -1; y <= 1; y++) {
            for(int x = -1; x <= 1; x++) {
                vec2 offs = vec2(float(x), float(y));
                vec2 cellId = id + offs;
                float life1 = getLife(cellId, t);

                if(life1 > 0.0) {
                    vec2 p1 = offs + 0.5 + 0.4 * sin(t * 1.5 + hash22(cellId) * 6.28);

                    float dNode = length(f - p1);
                    float rad = 0.06 * life1;

                    // Node Neon Logic
                    float px = 0.015;
                    float ring = smoothstep(rad + px, rad, dNode) - smoothstep(rad*0.5 + px, rad*0.5, dNode);
                    float core = smoothstep(rad*0.2 + px, rad*0.2, dNode);
                    nodeMask = max(nodeMask, (ring + core) * life1);

                    // Lush Neon Halo around nodes
                    nodeGlow = max(nodeGlow, exp(-dNode * 30.0) * u_neon_glow * life1);

                    evalConnection(f, p1, life1, offs, vec2(1.0, 0.0), id, t, connRadius, lineData, lineGlow);
                    evalConnection(f, p1, life1, offs, vec2(0.0, 1.0), id, t, connRadius, lineData, lineGlow);
                    evalConnection(f, p1, life1, offs, vec2(1.0, 1.0), id, t, connRadius, lineData, lineGlow);
                    evalConnection(f, p1, life1, offs, vec2(-1.0, 1.0), id, t, connRadius, lineData, lineGlow);
                }
            }
        }

        // --- Layer Compositing ---
        vec3 lCol = mix(baseCol, pulseCol, lineData.r * pulseInt);

        // Add Bloom/Glow to the line color
        vec3 neonLayer = lCol * lineData.a;
        neonLayer += lCol * lineGlow * 0.5; // Neon light leak

        // Add Nodes with their own glow
        vec3 nodeCol = mix(baseCol * 1.5, vec3(1.0), nodeMask);
        neonLayer = mix(neonLayer, nodeCol, nodeMask);
        neonLayer += baseCol * nodeGlow * 0.8;

        // Apply Z-Depth fade and global intensity
        float alpha = clamp(lineData.a + nodeMask + lineGlow * 0.2 + nodeGlow * 0.2, 0.0, 1.0);
        finalColor += neonLayer * fade * u_intensity;
    }

    // Lush Post-processing
    // Add a final "lush" glow pass based on the screen's center
    finalColor += baseCol * u_bloom * exp(-length(uv0) * 2.0);

    // Vibrant Vignette
    float vig = smoothstep(1.5, 0.2, length(uv0));
    finalColor *= vig;

    // Saturation boost for that neon pop
    finalColor = pow(finalColor, vec3(0.85));

    fragColor = vec4(finalColor, 1.0);
}
